SIZE_CLASSES = {
    "xs": "w-3 h-3",
    "sm": "w-4 h-4",
    "md": "w-5 h-5",
    "lg": "w-6 h-6",
    "xl": "w-8 h-8",
}


@register.simple_tag
def icon(name, size="md", extra_class=""):
    path_data = ICONS.get(name)
    if not path_data:
        return ""

    size_class = SIZE_CLASSES.get(size, SIZE_CLASSES["md"])
    css_classes = f"{size_class} {extra_class}".strip()

    svg = (
        f'<svg class="{css_classes}" '
        f'xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" '
        f'stroke="currentColor" stroke-width="1.5" aria-hidden="true">'
        f"{path_data}"
        f"</svg>"
    )
    return mark_safe(svg)
